def test_to_attr_value() -> None:
    when = datetime(2026, 1, 1, tzinfo=timezone.utc)
    assert to_attr_value({"a": [1, None, (2, 3)], "b": None, 4: when}) == {
        "a": [1, [2, 3]],
        "4": when.isoformat(),
    }
    assert to_attr_value({1}) == [1]
    assert to_attr_value(object.__new__(object)).startswith("<object")


def test_handler_forwards_records(logger_and_sink: Any) -> None:
    logger, sink, _ = logger_and_sink
    logger.warning("hello %s", "world", extra={"user": "bob", "obj": {"k": 1}})
    (record,) = sink.records
    assert record.body == "hello world"
    assert record.severity is Severity.WARN
    assert record.severity_text == "WARNING"
    attrs = dict(record.attributes)
    assert attrs["user"] == "bob"
    assert attrs["obj"] == {"k": 1}
    assert attrs["logger.name"] == "grow.test.adapter"
    assert attrs["code.function"] == "test_handler_forwards_records"
    assert isinstance(attrs["code.lineno"], int)
    assert attrs["thread.name"] == threading.current_thread().name
    assert "exception.type" not in attrs


def test_handler_exception_and_formatter(logger_and_sink: Any) -> None:
    logger, sink, handler = logger_and_sink
    try:
        raise ValueError("bad value")
    except ValueError:
        logger.exception("failed")
    attrs = dict(sink.records[0].attributes)
    assert attrs["exception.type"] == "ValueError"
    assert attrs["exception.message"] == "bad value"
    assert "Traceback" in str(attrs["exception.stacktrace"])
    handler.setFormatter(logging.Formatter("[%(levelname)s] %(message)s"))
    logger.error("formatted")
    assert sink.records[-1].body == "[ERROR] formatted"
    assert sink.records[-1].severity is Severity.ERROR


def test_handler_skips_excluded_loggers_and_worker_threads(logger_and_sink: Any) -> None:
    _, sink, handler = logger_and_sink
    excluded = logging.LogRecord("httpx", logging.INFO, __file__, 1, "x", None, None)
    nested = logging.LogRecord("httpcore.http11", logging.INFO, __file__, 1, "x", None, None)
    worker = logging.LogRecord("app", logging.INFO, __file__, 1, "x", None, None)
    worker.threadName = f"{WORKER_THREAD_PREFIX}-batch"
    kept = logging.LogRecord("httpxish", logging.INFO, __file__, 1, "x", None, None)
    kept.threadName = None  # type: ignore[assignment]
    for record in (excluded, nested, worker, kept):
        handler.emit(record)
    assert len(sink.records) == 1
    assert "thread.name" not in sink.records[0].attributes


def test_handler_reports_sink_errors(monkeypatch: pytest.MonkeyPatch) -> None:
    class Broken:
        def send(self, record: LogRecord | LogInput) -> None:
            raise RuntimeError("sink down")

    handler = LogHandler(Broken(), exclude_loggers=())
    reported: list[logging.LogRecord] = []
    monkeypatch.setattr(handler, "handleError", reported.append)
    record = logging.LogRecord("app", logging.INFO, __file__, 1, "x", None, None)
    handler.emit(record)
    assert reported == [record]


def test_structlog_processor_direct() -> None:
    sink = Sink()
    processor = structlog_processor(sink)
    event = {
        "event": "user login",
        "level": "warning",
        "timestamp": "2026-01-01T00:00:00Z",
        "user": "bob",
        "none": None,
        "exception": "Traceback ...",
    }
    assert processor(None, "warning", event) is event
    record = sink.records[0]
    assert record.body == "user login"
    assert record.severity is Severity.WARN
    assert record.severity_text == "WARNING"
    assert record.timestamp == datetime(2026, 1, 1, tzinfo=timezone.utc)
    assert dict(record.attributes) == {"user": "bob", "exception.stacktrace": "Traceback ..."}

    processor(None, "info", {"event": "epoch", "timestamp": 0.0})
    assert sink.records[-1].timestamp == datetime(1970, 1, 1, tzinfo=timezone.utc)
    naive = datetime(2026, 2, 2)
    processor(None, "debug", {"event": "naive", "timestamp": naive})
    assert sink.records[-1].timestamp == naive.replace(tzinfo=timezone.utc)
    assert sink.records[-1].severity is Severity.DEBUG
    processor(None, "", {"event": "odd", "level": "shout", "timestamp": "not a time"})
    assert sink.records[-1].severity is Severity.INFO
    assert sink.records[-1].timestamp.year >= 2026
    processor(None, "info", {"timestamp": object()})
    assert sink.records[-1].body == ""


def test_structlog_processor_exc_info() -> None:
    sink = Sink()
    processor = structlog_processor(sink)
    try:
        raise KeyError("k")
    except KeyError as exc:
        processor(None, "error", {"event": "a", "exc_info": True})
        processor(None, "error", {"event": "b", "exc_info": exc})
    processor(None, "error", {"event": "c", "exc_info": (None, None, None)})
    assert sink.records[0].attributes["exception.type"] == "KeyError"
    assert sink.records[1].attributes["exception.type"] == "KeyError"
    assert "exception.type" not in sink.records[2].attributes


def test_structlog_integration() -> None:
    structlog = pytest.importorskip("structlog")
    sink = Sink()
    captured: list[dict[str, Any]] = []

    def capture(logger: Any, method: str, event_dict: Any) -> str:
        captured.append(dict(event_dict))
        return "rendered"

    log = structlog.wrap_logger(
        structlog.PrintLogger(io.StringIO()),
        processors=[
            structlog.processors.add_log_level,
            structlog.processors.TimeStamper(fmt="iso", utc=True),
            structlog_processor(sink),
            capture,
        ],
    )
    log.info("hello", user="bob")
    assert sink.records[0].body == "hello"
    assert sink.records[0].attributes["user"] == "bob"
    assert captured[0]["event"] == "hello"
